serious.repro:
The test goes in crates/taskdeck-core/tests/probe_verify.rs. On 814b88c it fails with left: Err("core/cap"), right: Ok(()). The board passes `check()` at 61,865,895 bytes, with 46,757 archive rows and 6,134 bytes of notes.

use taskdeck_core::apply::{Ctx, apply};
use taskdeck_core::board::{ArchiveRow, BoardData, Item, ItemStamps, Kind, Mark, Outcome, Stamp};
use taskdeck_core::canon::Record;
use taskdeck_core::command::parse_command;
use taskdeck_core::compile::{CompileCtx, compile};
use taskdeck_core::ids::IdMinter;
use taskdeck_core::intent::parse_intent;
use taskdeck_core::overlay::Overlay;
use taskdeck_core::time::{FixedZone, Instant};
const S: Stamp = Stamp { seq: 1, device_no: 0 };
fn at(m: i64) -> Instant { Instant::from_parts(1_773_100_800 + m * 60, 0).expect("i") }
#[test]
fn compiled_add_is_refused_for_size() {
    let mut b = BoardData::empty();
    b.items = vec![Item { id: 1, kind: Kind::Task, name: "t".into(), created: at(0), deadline: None, importance: None, time_importance: None, duration_minutes: None, recurrence: None, blocks: vec![], stamps: ItemStamps { estimate: S, levels: S, name: S, repeat: S, time: S } }];
    b.marks = vec![Mark { device_no: 0, item: 1, block: 0 }];
    let name = "\u{1}".repeat(200);
    let mk = |k: i64| ArchiveRow { id: 0, kind: Kind::Task, name: name.clone(), created: at(0), deadline: None, importance: None, time_importance: None, duration_minutes: None, recurrence: None, blocks: vec![], archived_at: Instant::from_parts(1_000_000 + k, 0).expect("i"), outcome: Outcome::Finished };
    b.archive = vec![mk(0)]; let one = b.to_canonical().len();
    b.archive = vec![mk(0), mk(1)]; let per = b.to_canonical().len() - one;
    let n = 2 + (61_865_984 - b.to_canonical().len() - 5_000) / per;
    b.archive = (0..n as i64).map(mk).collect();
    let len = b.to_canonical().len();
    b.notes = "a".repeat(61_865_984 - len - 100);
    assert!(b.to_canonical().len() <= 61_865_984); assert!(b.check().is_ok());
    let overlay = Overlay::default();
    let cx = CompileCtx { view: &b, zone: &FixedZone(0), now: at(720), device_no: 1, overlay: &overlay };
    let mut m = IdMinter::new(1);
    let c = compile(&parse_intent(r#"{"op":"add","name":"Write something long enough","importance":1}"#).unwrap(), &cx, &mut m).expect("compiles").command.expect("cmd");
    assert_eq!(parse_command(&c.to_canonical()).as_ref(), Ok(&c));
    let r = apply(&mut b.clone(), &c, &Ctx { seq: 1000, device_no: 1, at: at(720), based_on: 999 }).map(|_| ()).map_err(|e| e.code);
    assert_eq!(r, Ok(()), "CORE-COMP-008");
}

The cause: `compile` never runs apply's size check (§8.4 step 4, CORE-APPLY-005, apply.rs `growth_bound`/`canonical_len`). Every growing command, including the creates, add_block, rename and set_notes, can therefore compile to a command that apply refuses with `core/cap`. The implementation has no SPEC-QUESTION at this point.
